"use client";

import { useCallback, useEffect, useId, useRef, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";

import { sampleDate } from "../lib/format";
import { usePointCursor } from "../lib/use-point-cursor";
import { BlockFrame } from "../parts/block-frame";
import { SeriesToggle } from "../parts/series-toggle";
import { ZoomInIcon, ZoomOutIcon } from "./icons";
import { CandleChart } from "./market-terminal/candle-chart";
import {
  AVERAGES,
  type AverageId,
  type Candle,
  HISTORY,
  movingAverage,
  RANGES,
  type RangeValue,
  TICKERS,
} from "./market-terminal/data";
import { type Order, OrderList } from "./market-terminal/order-list";
import { type OrderDraft, OrderTicket } from "./market-terminal/order-ticket";
import { PriceHeader } from "./market-terminal/price-header";
import { type Flash, Watchlist } from "./market-terminal/watchlist";

const TICK_MS = 1600;
const FLASH_MS = 700;
const FILL_MS = 900;
const FEWEST_DAYS = 12;

const startingCandles = () =>
  Object.fromEntries(TICKERS.map((ticker) => [ticker.symbol, ticker.candles]));

/** Moves today's candle of one series by a small random step. */
function tick(series: Candle[]): Candle[] {
  const today = series[series.length - 1];
  if (!today) return series;
  const close = Math.max(1, today.close * (1 + (Math.random() - 0.5) * 0.006));
  const next = {
    ...today,
    close,
    high: Math.max(today.high, close),
    low: Math.min(today.low, close),
    volume: today.volume + Math.random() * today.volume * 0.004,
  };
  return [...series.slice(0, -1), next];
}

/** Whether a working limit order would fill at this price. */
const crosses = (order: Order, price: number) =>
  order.type === "limit" &&
  order.limit !== undefined &&
  (order.side === "buy" ? price <= order.limit : price >= order.limit);

/**
 * A trading screen for a watchlist of invented clinic companies: the price,
 * a candlestick chart with volume and two averages, a live feed that flashes
 * moving prices, and a ticket that places market and limit orders.
 */
export function MarketTerminal({ className }: { className?: string }) {
  const titleId = useId();
  const groupId = useId();
  const [candles, setCandles] =
    useState<Record<string, Candle[]>>(startingCandles);
  const [symbol, setSymbol] = useState(TICKERS[0]!.symbol);
  const [live, setLive] = useState(true);
  const [range, setRange] = useState<RangeValue>("63");
  const [count, setCount] = useState(63);
  const [offset, setOffset] = useState(0);
  const [shown, setShown] = useState<Record<AverageId, boolean>>({
    short: true,
    long: true,
  });
  const [flashes, setFlashes] = useState<Record<string, Flash | undefined>>({});
  const [orders, setOrders] = useState<Order[]>([]);
  const [notice, setNotice] = useState("");
  const timers = useRef(new Set<number>());
  const nextId = useRef(1);
  const cursor = usePointCursor(count, 5);

  const candlesRef = useRef(candles);

  useEffect(() => {
    candlesRef.current = candles;
  }, [candles]);

  const later = useCallback((run: () => void, wait: number) => {
    const timer = window.setTimeout(() => {
      timers.current.delete(timer);
      run();
    }, wait);
    timers.current.add(timer);
  }, []);

  useEffect(() => {
    const pending = timers.current;
    return () => pending.forEach((timer) => window.clearTimeout(timer));
  }, []);

  // The feed moves every price a little, flashes the ones that moved and fills limit orders the price crossed.
  useEffect(() => {
    if (!live) return;
    const interval = window.setInterval(() => {
      const current = candlesRef.current;
      const next = Object.fromEntries(
        Object.entries(current).map(([key, series]) => [key, tick(series)]),
      );
      const moved: Record<string, Flash> = {};
      for (const [key, series] of Object.entries(next)) {
        moved[key] =
          (series.at(-1)?.close ?? 0) >= (current[key]?.at(-1)?.close ?? 0)
            ? "up"
            : "down";
      }
      candlesRef.current = next;
      setCandles(next);
      setFlashes(moved);
      setOrders((list) =>
        list.map((order) => {
          const now = next[order.symbol]?.at(-1)?.close ?? 0;
          return order.status === "working" && crosses(order, now)
            ? { ...order, status: "filled", fillPrice: order.limit }
            : order;
        }),
      );
      later(() => setFlashes({}), FLASH_MS);
    }, TICK_MS);
    return () => window.clearInterval(interval);
  }, [live, later]);

  const ticker = TICKERS.find((item) => item.symbol === symbol) ?? TICKERS[0]!;
  const series = candles[symbol] ?? ticker.candles;
  const price = series.at(-1)?.close ?? 0;
  const start = Math.max(0, HISTORY - offset - count);
  const visible = series.slice(start, start + count);
  const averages = {
    short: movingAverage(series, AVERAGES[0].days).slice(start, start + count),
    long: movingAverage(series, AVERAGES[1].days).slice(start, start + count),
  } satisfies Record<AverageId, (number | null)[]>;

  const zoom = (factor: number) => {
    setCount((current) =>
      Math.min(
        HISTORY - offset,
        Math.max(FEWEST_DAYS, Math.round(current * factor)),
      ),
    );
  };

  const pan = (days: number) => {
    setOffset((current) =>
      Math.min(HISTORY - count, Math.max(0, current + days)),
    );
  };

  const place = (draft: OrderDraft) => {
    const id = nextId.current;
    nextId.current += 1;
    const filledNow =
      draft.type === "limit" &&
      crosses({ ...draft, id, symbol, status: "working" }, price);
    setOrders((list) => [
      {
        ...draft,
        id,
        symbol,
        status: filledNow ? "filled" : "working",
        fillPrice: filledNow ? draft.limit : undefined,
      },
      ...list,
    ]);
    setNotice(
      `${draft.side === "buy" ? "Buy" : "Sell"} order for ${draft.quantity} ${symbol} placed.`,
    );
    if (draft.type === "market") {
      later(() => {
        const now = candlesRef.current[symbol]?.at(-1)?.close ?? price;
        setOrders((list) =>
          list.map((order) =>
            order.id === id && order.status === "working"
              ? { ...order, status: "filled", fillPrice: now }
              : order,
          ),
        );
        setNotice(`${draft.quantity} ${symbol} filled.`);
      }, FILL_MS);
    }
  };

  const cancel = (id: number) => {
    setOrders((list) =>
      list.map((order) =>
        order.id === id && order.status === "working"
          ? { ...order, status: "cancelled" }
          : order,
      ),
    );
    setNotice("Order cancelled.");
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <PriceHeader
        ticker={ticker}
        candles={series}
        live={live}
        onLiveChange={setLive}
        titleId={titleId}
      />
      <div className="grid @4xl:grid-cols-[1fr_19rem]">
        <div className="flex min-w-0 flex-col gap-3 border-b border-border p-5 @4xl:border-r @4xl:border-b-0">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <SegmentedControl
              aria-label="Chart range"
              options={[...RANGES]}
              value={range}
              onValueChange={(next) => {
                setRange(next);
                setCount(Number(next));
                setOffset(0);
              }}
            />
            <div className="flex flex-wrap items-center gap-2">
              {AVERAGES.map((average) => (
                <SeriesToggle
                  key={average.id}
                  label={average.label}
                  swatch={average.swatch}
                  checked={shown[average.id]}
                  onCheckedChange={(checked) =>
                    setShown((current) => ({
                      ...current,
                      [average.id]: checked,
                    }))
                  }
                />
              ))}
              <Button
                type="button"
                variant="ghost"
                size="icon"
                aria-label="Zoom in"
                onClick={() => zoom(1 / 1.5)}
                disabled={count <= FEWEST_DAYS}
              >
                <ZoomInIcon aria-hidden="true" />
              </Button>
              <Button
                type="button"
                variant="ghost"
                size="icon"
                aria-label="Zoom out"
                onClick={() => zoom(1.5)}
                disabled={count >= HISTORY - offset}
              >
                <ZoomOutIcon aria-hidden="true" />
              </Button>
            </div>
          </div>
          <CandleChart
            symbol={symbol}
            candles={visible}
            averages={averages}
            shown={shown}
            dateOf={(index) => sampleDate(HISTORY - 1 - (start + index))}
            cursor={cursor}
            onZoom={zoom}
            onPan={pan}
          />
        </div>
        <div className="flex min-w-0 flex-col gap-6 p-5">
          <Watchlist
            tickers={TICKERS}
            candles={candles}
            flashes={flashes}
            selected={symbol}
            onSelect={setSymbol}
            groupId={groupId}
          />
          <div className="border-t border-border pt-5">
            <OrderTicket
              key={symbol}
              symbol={symbol}
              price={price}
              onPlace={place}
            />
          </div>
          <OrderList orders={orders} onCancel={cancel} />
        </div>
      </div>
      <p aria-live="polite" className="sr-only">
        {notice}
      </p>
    </BlockFrame>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

"use client";

import { type KeyboardEvent, type PointerEvent, useCallback, useState } from "react";

/** What a chart needs to let a person inspect one point with a pointer or the keyboard. */
export interface PointCursor {
  /** The inspected point, or null when nothing is inspected. */
  index: number | null;
  setIndex: (index: number | null) => void;
  /** Spread onto the focusable plot. Arrows step, Page keys jump, Home and End go to the ends, Escape clears. */
  plotProps: {
    tabIndex: 0;
    onKeyDown: (event: KeyboardEvent<HTMLElement>) => void;
    /** A tap or a press inspects the point under it, so a touch screen needs no hover. */
    onPointerDown: (event: PointerEvent<HTMLElement>) => void;
    onPointerMove: (event: PointerEvent<HTMLElement>) => void;
    onPointerLeave: (event: PointerEvent<HTMLElement>) => void;
    /** A finger can scrub across the plot while the page still scrolls up and down. */
    style: { touchAction: "pan-y" };
    onBlur: () => void;
  };
}

/**
 * Tracks the inspected point of a plot with `length` points. `pageStep` is how
 * far the Page keys and Shift with an arrow jump.
 */
export function usePointCursor(length: number, pageStep = 7): PointCursor {
  const [raw, setIndex] = useState<number | null>(null);
  // A shorter range can leave the cursor past the end, so clamp on read.
  const index = raw === null ? null : Math.min(raw, length - 1);

  const onKeyDown = useCallback(
    (event: KeyboardEvent<HTMLElement>) => {
      const last = length - 1;
      const current = index ?? last;
      const big = event.shiftKey ? pageStep : 1;
      let next: number | null;
      if (event.key === "ArrowLeft") next = index === null ? last : Math.max(0, current - big);
      else if (event.key === "ArrowRight") next = index === null ? last : Math.min(last, current + big);
      else if (event.key === "PageUp") next = Math.max(0, current - pageStep);
      else if (event.key === "PageDown") next = Math.min(last, current + pageStep);
      else if (event.key === "Home") next = 0;
      else if (event.key === "End") next = last;
      else if (event.key === "Escape" && index !== null) next = null;
      else return;
      event.preventDefault();
      setIndex(next);
    },
    [index, length, pageStep],
  );

  const onPointerMove = useCallback(
    (event: PointerEvent<HTMLElement>) => {
      const box = event.currentTarget.getBoundingClientRect();
      if (box.width === 0) return;
      const ratio = Math.min(1, Math.max(0, (event.clientX - box.left) / box.width));
      setIndex(Math.round(ratio * (length - 1)));
    },
    [length],
  );

  const clear = useCallback(() => setIndex(null), []);

  // A finger leaves the plot the moment it lifts. Clearing then would hide the point a tap just chose,
  // so only a mouse clears on the way out. A tapped point stays until the plot loses focus.
  const onPointerLeave = useCallback((event: PointerEvent<HTMLElement>) => {
    if (event.pointerType === "mouse") setIndex(null);
  }, []);

  return {
    index,
    setIndex,
    plotProps: {
      tabIndex: 0,
      onKeyDown,
      onPointerDown: onPointerMove,
      onPointerMove,
      onPointerLeave,
      onBlur: clear,
      style: { touchAction: "pan-y" },
    },
  };
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import { Checkbox } from "@/components/ui/checkbox";
import { cn } from "@/lib/utils";

/** Props for a legend entry that shows or hides one series. */
export interface SeriesToggleProps {
  label: string;
  /** The background class of the series colour, such as `bg-chart-1`. */
  swatch: string;
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
}

/** A legend entry that is also a checkbox: it names a series and shows or hides it. */
export function SeriesToggle({ label, swatch, checked, onCheckedChange }: SeriesToggleProps) {
  return (
    <label
      className={cn(
        "whitespace-nowrap inline-flex min-h-11 cursor-pointer items-center gap-2 rounded-full border border-border px-3 text-sm sm:min-h-9",
        "has-focus-visible:ring-2 has-focus-visible:ring-ring",
        checked ? "text-foreground" : "text-muted-foreground line-through",
      )}
    >
      <Checkbox checked={checked} onCheckedChange={(value) => onCheckedChange(value === true)} className="sr-only" />
      <span aria-hidden="true" className={cn("size-2.5 rounded-sm", checked ? swatch : "border border-muted-foreground")} />
      {label}
    </label>
  );
}

