"use client";

import {
  type KeyboardEvent,
  type PointerEvent,
  useEffect,
  useRef,
} from "react";

import { cn } from "@/lib/utils";

import { formatDay } from "../../lib/format";
import { niceScale } from "../../lib/nice-scale";
import type { PointCursor } from "../../lib/use-point-cursor";
import {
  AVERAGES,
  type AverageId,
  type Candle,
  formatPrice,
  formatShares,
} from "./data";
import { useEasedRange } from "./use-eased-range";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for the candlestick chart. */
export interface CandleChartProps {
  symbol: string;
  /** The candles in view, oldest first. */
  candles: Candle[];
  /** The moving averages in view, aligned with `candles`. */
  averages: Record<AverageId, (number | null)[]>;
  shown: Record<AverageId, boolean>;
  dateOf: (index: number) => Date;
  cursor: PointCursor;
  /** Zooms by a factor: above 1 shows more days, below 1 fewer. */
  onZoom: (factor: number) => void;
  /** Moves the window by a number of days: positive goes back in time. */
  onPan: (days: number) => void;
}

const span = (value: number, [low, high]: [number, number]) =>
  100 - ((value - low) / (high - low || 1)) * 100;

/** A path through the values that skips the days with no average yet. */
function averagePath(
  values: (number | null)[],
  range: [number, number],
): string {
  const width = 100 / values.length;
  let path = "";
  values.forEach((value, index) => {
    if (value === null) return;
    path += `${path ? "L" : "M"}${((index + 0.5) * width).toFixed(2)} ${span(value, range).toFixed(2)} `;
  });
  return path;
}

/** The readout text for one candle, the same for the eye and the live region. */
function describe(candle: Candle, previous: Candle | undefined, date: Date) {
  const change = previous
    ? ((candle.close - previous.close) / previous.close) * 100
    : 0;
  return {
    date: formatDay(date),
    fields: [
      ["Open", formatPrice(candle.open)],
      ["High", formatPrice(candle.high)],
      ["Low", formatPrice(candle.low)],
      ["Close", formatPrice(candle.close)],
      ["Volume", formatShares(candle.volume)],
    ] as const,
    change,
  };
}

/**
 * Daily candles with volume under them and two optional moving averages. The
 * plot is one tab stop: arrows move the crosshair a day, plus and minus zoom,
 * Escape clears. A trackpad pinch zooms, a sideways swipe or a mouse drag pans,
 * and the price scale eases to each new window.
 */
export function CandleChart({
  symbol,
  candles,
  averages,
  shown,
  dateOf,
  cursor,
  onZoom,
  onPan,
}: CandleChartProps) {
  const plotRef = useRef<HTMLDivElement | null>(null);
  const drag = useRef<{ x: number; moved: number } | null>(null);
  const zoomRef = useRef(onZoom);
  const panRef = useRef(onPan);
  zoomRef.current = onZoom;
  panRef.current = onPan;
  const count = candles.length;

  let low = Infinity;
  let high = -Infinity;
  let loudest = 1;
  for (const candle of candles) {
    low = Math.min(low, candle.low);
    high = Math.max(high, candle.high);
    loudest = Math.max(loudest, candle.volume);
  }
  const pad = (high - low) * 0.08 || 1;
  const range = useEasedRange([low - pad, high + pad]);
  const ticks = niceScale(low - pad, high + pad, 4).ticks.filter(
    (tick) => tick >= range[0] && tick <= range[1],
  );

  // A pinch reaches the page as a wheel event with Ctrl held. React listens passively, so the plot listens itself to keep the page still.
  useEffect(() => {
    const plot = plotRef.current;
    if (!plot) return;
    const onWheel = (event: WheelEvent) => {
      if (event.ctrlKey) {
        event.preventDefault();
        zoomRef.current(event.deltaY > 0 ? 1.12 : 1 / 1.12);
      } else if (Math.abs(event.deltaX) > Math.abs(event.deltaY)) {
        event.preventDefault();
        panRef.current(Math.round(event.deltaX / -12));
      }
    };
    plot.addEventListener("wheel", onWheel, { passive: false });
    return () => plot.removeEventListener("wheel", onWheel);
  }, []);

  const indexAt = (event: PointerEvent<HTMLDivElement>) => {
    const box = event.currentTarget.getBoundingClientRect();
    if (box.width === 0) return null;
    return Math.min(
      count - 1,
      Math.max(0, Math.floor(((event.clientX - box.left) / box.width) * count)),
    );
  };

  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (event.pointerType === "mouse")
      drag.current = { x: event.clientX, moved: 0 };
    cursor.setIndex(indexAt(event));
  };

  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const start = drag.current;
    if (start && event.buttons === 1) {
      const width = event.currentTarget.getBoundingClientRect().width || 1;
      const days = Math.round(((event.clientX - start.x) / width) * count);
      if (days !== start.moved) {
        onPan(days - start.moved);
        start.moved = days;
      }
      return;
    }
    cursor.setIndex(indexAt(event));
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "+" || event.key === "=") onZoom(1 / 1.5);
    else if (event.key === "-") onZoom(1.5);
    else return cursor.plotProps.onKeyDown(event);
    event.preventDefault();
  };

  const index = cursor.index;
  const shownIndex = index ?? count - 1;
  const inspected = candles[shownIndex];
  const reading = inspected
    ? describe(inspected, candles[shownIndex - 1], dateOf(shownIndex))
    : null;
  const last = candles[count - 1];
  const width = 100 / count;

  return (
    <div className="flex min-w-0 flex-col gap-2">
      <p className="flex min-h-5 flex-wrap items-center gap-x-3 gap-y-1 text-xs tabular-nums text-muted-foreground">
        {reading ? (
          <>
            <span className="font-medium text-foreground">{reading.date}</span>
            {reading.fields.map(([label, value]) => (
              <span key={label}>
                {label} <span className="text-foreground">{value}</span>
              </span>
            ))}
            <span
              className={
                reading.change >= 0
                  ? "text-marketing-green-ink"
                  : "text-marketing-orange-ink"
              }
            >
              {reading.change >= 0 ? "+" : "-"}
              {Math.abs(reading.change).toFixed(2)}%
            </span>
          </>
        ) : null}
      </p>
      <p aria-live="polite" className="sr-only">
        {index !== null && reading
          ? `${reading.date}. ${reading.fields.map(([label, value]) => `${label} ${value}`).join(", ")}.`
          : ""}
      </p>
      <div className="flex min-w-0 flex-col gap-1">
        <div className="flex gap-2">
          <div
            ref={plotRef}
            {...cursor.plotProps}
            onKeyDown={onKeyDown}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={() => {
              drag.current = null;
            }}
            role="application"
            aria-roledescription="chart"
            aria-label={`${symbol} daily prices, ${count} days. Arrow keys move one day, plus and minus zoom.`}
            className="relative h-60 min-w-0 flex-1 cursor-crosshair rounded-md outline-none select-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-4 focus-visible:ring-offset-card @2xl:h-72 @4xl:h-96"
          >
            <div aria-hidden="true" className="absolute inset-0">
              {ticks.map((tick) => (
                <span
                  key={tick}
                  className="top-(--y) absolute inset-x-0 h-px bg-border/60"
                  style={
                    // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                    { "--y": `${span(tick, range)}%` } as VarStyle
                  }
                />
              ))}
            </div>
            <svg
              aria-hidden="true"
              viewBox="0 0 100 100"
              preserveAspectRatio="none"
              className="absolute inset-0 size-full overflow-visible"
            >
              {candles.map((candle, position) => {
                const up = candle.close >= candle.open;
                const top = span(Math.max(candle.open, candle.close), range);
                const bottom = span(Math.min(candle.open, candle.close), range);
                const centre = (position + 0.5) * width;
                return (
                  <g
                    key={position}
                    className={cn(
                      up
                        ? "fill-marketing-green-ink stroke-marketing-green-ink"
                        : "fill-marketing-orange-ink stroke-marketing-orange-ink",
                      "motion-safe:transition-opacity motion-safe:duration-150",
                      index !== null && index !== position && "opacity-40",
                    )}
                  >
                    <line
                      x1={centre}
                      x2={centre}
                      y1={span(candle.high, range)}
                      y2={span(candle.low, range)}
                      strokeWidth="1"
                      vectorEffect="non-scaling-stroke"
                    />
                    <rect
                      x={centre - width * 0.32}
                      width={width * 0.64}
                      y={top}
                      height={Math.max(0.35, bottom - top)}
                      strokeWidth="0"
                    />
                  </g>
                );
              })}
              {AVERAGES.map((average) =>
                shown[average.id] ? (
                  <path
                    key={average.id}
                    d={averagePath(averages[average.id], range)}
                    fill="none"
                    strokeWidth="1.5"
                    strokeLinejoin="round"
                    vectorEffect="non-scaling-stroke"
                    className={average.stroke}
                  />
                ) : null,
              )}
            </svg>
            {index !== null && inspected ? (
              <div
                aria-hidden="true"
                className="pointer-events-none absolute inset-0"
              >
                <span
                  className="left-(--x) absolute inset-y-0 w-px bg-foreground/40"
                  style={
                    // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                    { "--x": `${(index + 0.5) * width}%` } as VarStyle
                  }
                />
                <span
                  className="top-(--y) absolute inset-x-0 h-px border-t border-dashed border-foreground/40"
                  style={
                    // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                    { "--y": `${span(inspected.close, range)}%` } as VarStyle
                  }
                />
              </div>
            ) : null}
          </div>
          <div
            aria-hidden="true"
            className="relative w-14 shrink-0 text-xs tabular-nums text-muted-foreground"
          >
            {ticks.map((tick) => (
              <span
                key={tick}
                className="top-(--y) absolute left-0 -translate-y-1/2"
                style={
                  // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                  { "--y": `${span(tick, range)}%` } as VarStyle
                }
              >
                {tick.toFixed(tick < 20 ? 1 : 0)}
              </span>
            ))}
            {last ? (
              <span
                className="top-(--y) absolute left-0 -translate-y-1/2 rounded-md bg-foreground px-1.5 py-0.5 font-medium text-background"
                style={
                  // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                  {
                    "--y": `${Math.min(100, Math.max(0, span(last.close, range)))}%`,
                  } as VarStyle
                }
              >
                {last.close.toFixed(2)}
              </span>
            ) : null}
          </div>
        </div>
        <div className="pr-16">
          <svg
            aria-hidden="true"
            viewBox="0 0 100 100"
            preserveAspectRatio="none"
            className="block h-12 w-full"
          >
            {candles.map((candle, position) => {
              const tall = (candle.volume / loudest) * 100;
              return (
                <rect
                  key={position}
                  x={(position + 0.12) * width}
                  width={width * 0.76}
                  y={100 - tall}
                  height={tall}
                  className={cn(
                    candle.close >= candle.open
                      ? "fill-marketing-green-ink/40"
                      : "fill-marketing-orange-ink/40",
                    index !== null && index !== position && "opacity-40",
                  )}
                />
              );
            })}
          </svg>
          <div
            aria-hidden="true"
            className="mt-1 flex justify-between text-xs text-muted-foreground"
          >
            <span>{formatDay(dateOf(0))}</span>
            <span>{formatDay(dateOf(Math.floor((count - 1) / 2)))}</span>
            <span>{formatDay(dateOf(count - 1))}</span>
          </div>
        </div>
      </div>
    </div>
  );
}

/** An axis that starts and ends on round values, with a tick at every step between. */
export interface NiceScale {
  low: number;
  high: number;
  step: number;
  ticks: number[];
}

/** The nearest round step at or above `raw`: 1, 2, 2.5 or 5 times a power of ten. */
export function niceStep(raw: number): number {
  if (!(raw > 0)) return 1;
  const power = 10 ** Math.floor(Math.log10(raw));
  const factor = raw / power;
  const round = factor <= 1 ? 1 : factor <= 2 ? 2 : factor <= 2.5 ? 2.5 : factor <= 5 ? 5 : 10;
  return round * power;
}

/** A round axis that holds `low` to `high` in about `count` steps. */
export function niceScale(low: number, high: number, count = 4): NiceScale {
  const step = niceStep((high - low || 1) / count);
  const first = Math.floor(low / step);
  const last = Math.max(first + 1, Math.ceil(high / step));
  const ticks = Array.from({ length: last - first + 1 }, (_, index) => (first + index) * step);
  return { low: first * step, high: last * step, step, ticks };
}

import { seededRandom } from "../../lib/plot";

/** One trading day: the four prices and the shares traded. */
export interface Candle {
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

/** One listed company in the watchlist, with its daily history, oldest first. */
export interface Ticker {
  symbol: string;
  name: string;
  exchange: string;
  candles: Candle[];
}

/** How many trading days of history each ticker has. */
export const HISTORY = 260;

/** Builds a repeatable random walk of daily candles that ends near `end`. */
function makeCandles(
  seed: number,
  start: number,
  end: number,
  swing: number,
  baseVolume: number,
): Candle[] {
  const random = seededRandom(seed);
  const candles: Candle[] = [];
  let close = start;
  for (let day = 0; day < HISTORY; day += 1) {
    const pull = (start + ((end - start) * day) / (HISTORY - 1) - close) * 0.08;
    const wave = Math.sin(day / 17) * swing * 0.25;
    const open = close + (random() - 0.5) * swing * 0.4;
    const next = Math.max(
      4,
      open + pull + wave * 0.2 + (random() - 0.5) * swing,
    );
    const high = Math.max(open, next) + random() * swing * 0.45;
    const low = Math.max(1, Math.min(open, next) - random() * swing * 0.45);
    const volume =
      baseVolume *
      (0.55 + random() * 0.9) *
      (1 + Math.abs(next - open) / swing);
    candles.push({ open, high, low, close: next, volume });
    close = next;
  }
  return candles;
}

