/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

"use client";

import { type FormEvent, useId, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

import { formatPrice } from "./data";

/** Buy or sell. */
export type Side = "buy" | "sell";
/** At the market price now, or only at a set price or better. */
export type OrderType = "market" | "limit";

/** What the ticket hands over when a person places an order. */
export interface OrderDraft {
  side: Side;
  type: OrderType;
  quantity: number;
  /** The set price of a limit order. */
  limit?: number;
}

/** Props for the order ticket. */
export interface OrderTicketProps {
  symbol: string;
  price: number;
  onPlace: (draft: OrderDraft) => void;
}

const SIDES: { value: Side; label: string }[] = [
  { value: "buy", label: "Buy" },
  { value: "sell", label: "Sell" },
];

const TYPES: { value: OrderType; label: string }[] = [
  { value: "market", label: "Market" },
  { value: "limit", label: "Limit" },
];

/**
 * A form for one order: buy or sell, market or limit, the share count and,
 * for a limit order, the price. The total updates as the price moves.
 */
export function OrderTicket({ symbol, price, onPlace }: OrderTicketProps) {
  const [side, setSide] = useState<Side>("buy");
  const [type, setType] = useState<OrderType>("market");
  const [quantity, setQuantity] = useState("10");
  const [limit, setLimit] = useState(() => price.toFixed(2));
  const quantityId = useId();
  const limitId = useId();
  const count = Math.max(0, Math.floor(Number(quantity) || 0));
  const limitValue = Number(limit) || 0;
  const valid = count > 0 && (type === "market" || limitValue > 0);
  const total = count * (type === "limit" ? limitValue : price);

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!valid) return;
    onPlace({
      side,
      type,
      quantity: count,
      limit: type === "limit" ? limitValue : undefined,
    });
  };

  return (
    <form
      onSubmit={submit}
      aria-label={`Order ${symbol}`}
      className="flex flex-col gap-3"
    >
      <h3 className="text-sm font-medium">Order {symbol}</h3>
      <div className="flex flex-wrap gap-2">
        <SegmentedControl
          aria-label="Buy or sell"
          options={SIDES}
          value={side}
          onValueChange={setSide}
        />
        <SegmentedControl
          aria-label="Order type"
          options={TYPES}
          value={type}
          onValueChange={(next) => {
            setType(next);
            if (next === "limit") setLimit(price.toFixed(2));
          }}
        />
      </div>
      <div className="grid grid-cols-2 gap-3">
        <label
          htmlFor={quantityId}
          className="flex flex-col gap-1 text-xs text-muted-foreground"
        >
          Shares
          <Input
            id={quantityId}
            type="number"
            inputMode="numeric"
            min={1}
            step={1}
            value={quantity}
            onChange={(event) => setQuantity(event.target.value)}
          />
        </label>
        {type === "limit" ? (
          <label
            htmlFor={limitId}
            className="flex flex-col gap-1 text-xs text-muted-foreground"
          >
            Limit price
            <Input
              id={limitId}
              type="number"
              inputMode="decimal"
              min={0.01}
              step={0.01}
              value={limit}
              onChange={(event) => setLimit(event.target.value)}
            />
          </label>
        ) : (
          <div className="flex flex-col gap-1 text-xs text-muted-foreground">
            Market price
            <span className="flex h-9 items-center text-sm font-medium text-foreground tabular-nums">
              {formatPrice(price)}
            </span>
          </div>
        )}
      </div>
      <p className="flex justify-between text-sm">
        <span className="text-muted-foreground">Estimated total</span>
        <span className="font-medium tabular-nums">{formatPrice(total)}</span>
      </p>
      <Button
        type="submit"
        disabled={!valid}
        variant={side === "buy" ? "default" : "secondary"}
      >
        {side === "buy" ? "Place buy order" : "Place sell order"}
      </Button>
    </form>
  );
}

"use client";

import { useId } from "react";

import { Switch } from "@/components/motion/switch";
import { cn } from "@/lib/utils";

import { RollingText } from "../../parts/rolling-text";
import {
  type Candle,
  formatChange,
  formatPrice,
  formatShares,
  type Ticker,
} from "./data";

/** Props for the price header. */
export interface PriceHeaderProps {
  ticker: Ticker;
  candles: Candle[];
  live: boolean;
  onLiveChange: (live: boolean) => void;
  titleId: string;
}

/**
 * The chosen company's name, its last price with the day's change, and the
 * day's open, high, low and volume. The Live switch starts and stops the feed.
 */
export function PriceHeader({
  ticker,
  candles,
  live,
  onLiveChange,
  titleId,
}: PriceHeaderProps) {
  const liveId = useId();
  const today = candles[candles.length - 1];
  const before = candles[candles.length - 2];
  if (!today) return null;
  const change = before ? today.close - before.close : 0;
  const percent = before ? (change / before.close) * 100 : 0;
  const figures = [
    ["Open", formatPrice(today.open)],
    ["High", formatPrice(today.high)],
    ["Low", formatPrice(today.low)],
    ["Volume", formatShares(today.volume)],
  ] as const;

  return (
    <header className="flex flex-wrap items-start justify-between gap-x-6 gap-y-4 border-b border-border px-5 py-4">
      <div className="flex min-w-0 flex-col gap-1">
        <h2
          id={titleId}
          className="flex items-baseline gap-2 text-base font-semibold"
        >
          {ticker.symbol}
          <span className="truncate text-sm font-normal text-muted-foreground">
            {ticker.name}, {ticker.exchange}
          </span>
        </h2>
        <p className="flex flex-wrap items-baseline gap-x-3 gap-y-1">
          <RollingText
            text={formatPrice(today.close)}
            className="text-3xl font-semibold tracking-tight"
          />
          <span
            className={cn(
              "text-sm font-medium tabular-nums",
              change >= 0
                ? "text-marketing-green-ink"
                : "text-marketing-orange-ink",
            )}
          >
            <span className="sr-only">{change >= 0 ? "Up" : "Down"} </span>
            {formatChange(change, percent)} today
          </span>
        </p>
        <dl className="mt-1 flex flex-wrap gap-x-5 gap-y-1 text-xs">
          {figures.map(([label, value]) => (
            <div key={label} className="flex flex-col">
              <dt className="text-muted-foreground">{label}</dt>
              <dd className="font-medium tabular-nums">{value}</dd>
            </div>
          ))}
        </dl>
      </div>
      <label
        htmlFor={liveId}
        className="flex min-h-11 cursor-pointer items-center gap-2 rounded-full border border-border px-3 text-sm sm:min-h-9"
      >
        <span
          aria-hidden="true"
          className={cn(
            "size-2 rounded-full",
            live
              ? "bg-marketing-green-ink motion-safe:animate-pulse"
              : "bg-muted-foreground",
          )}
        />
        Live
        <Switch id={liveId} checked={live} onCheckedChange={onLiveChange} />
      </label>
    </header>
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

"use client";

import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { cn } from "@/lib/utils";

import { RollingText } from "../../parts/rolling-text";
import { Sparkline } from "../../parts/sparkline";
import { type Candle, formatPrice, type Ticker } from "./data";

/** Which way a price last moved, for its brief flash. */
export type Flash = "up" | "down";

/** Props for the watchlist. */
export interface WatchlistProps {
  tickers: Ticker[];
  candles: Record<string, Candle[]>;
  flashes: Record<string, Flash | undefined>;
  selected: string;
  onSelect: (symbol: string) => void;
  groupId: string;
}

/**
 * The companies a person follows, as a radio group: the chosen row is the
 * one on the chart. Each row shows a month of closes and the last price, and
 * the price cell flashes green or orange when the feed moves it.
 */
export function Watchlist({
  tickers,
  candles,
  flashes,
  selected,
  onSelect,
  groupId,
}: WatchlistProps) {
  return (
    <div className="flex min-w-0 flex-col">
      <span id={`${groupId}-label`} className="mb-2 text-sm font-medium">
        Watchlist
      </span>
      <RadioGroup
        name={groupId}
        value={selected}
        onValueChange={onSelect}
        aria-labelledby={`${groupId}-label`}
        className="min-w-0"
      >
      {tickers.map((ticker) => {
        const series = candles[ticker.symbol] ?? ticker.candles;
        const last = series[series.length - 1]?.close ?? 0;
        const previous = series[series.length - 2]?.close ?? last;
        const change = previous ? ((last - previous) / previous) * 100 : 0;
        const checked = ticker.symbol === selected;
        const flash = flashes[ticker.symbol];
        return (
          <label
            key={ticker.symbol}
            className="group relative isolate grid min-h-12 cursor-pointer grid-cols-[1fr_auto_auto] items-center gap-3 rounded-lg px-3 py-2 has-focus-visible:ring-2 has-focus-visible:ring-ring"
          >
            <span
              aria-hidden="true"
              className={cn(
                "absolute inset-0 -z-10 rounded-lg",
                checked ? "bg-muted" : "group-hover:bg-muted/50",
              )}
            />
            <RadioGroupItem value={ticker.symbol} className="sr-only" />
            <span className="flex min-w-0 flex-col">
              <span className="text-sm font-medium">{ticker.symbol}</span>
              <span className="truncate text-xs text-muted-foreground">
                {ticker.name}
              </span>
            </span>
            <Sparkline
              values={series.slice(-30).map((candle) => candle.close)}
              className={cn(
                "h-7 w-14",
                change >= 0
                  ? "text-marketing-green-ink"
                  : "text-marketing-orange-ink",
              )}
            />
            <span className="flex flex-col items-end">
              <span
                className={cn(
                  "rounded px-1 text-sm font-medium motion-safe:transition-colors motion-safe:duration-500",
                  flash === "up" &&
                    "bg-marketing-green-surface text-marketing-green-ink",
                  flash === "down" &&
                    "bg-marketing-orange-surface text-marketing-orange-ink",
                )}
              >
                <RollingText text={formatPrice(last)} />
              </span>
              <span
                className={cn(
                  "px-1 text-xs tabular-nums",
                  change >= 0
                    ? "text-marketing-green-ink"
                    : "text-marketing-orange-ink",
                )}
              >
                {change >= 0 ? "+" : "-"}
                {Math.abs(change).toFixed(2)}%
              </span>
            </span>
          </label>
        );
      })}
      </RadioGroup>
    </div>
  );
}

import { cn } from "@/lib/utils";

import { linePath, paddedExtent } from "../lib/plot";

/** Props for a sparkline. */
export interface SparklineProps {
  values: number[];
  className?: string;
}

/** A small trend line with no axis. Decorative: the figure beside it carries the number. */
export function Sparkline({ values, className }: SparklineProps) {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 100 100"
      preserveAspectRatio="none"
      className={cn("h-8 w-20 overflow-visible text-muted-foreground", className)}
    >
      <path
        d={linePath(values, paddedExtent([values], 0.15), 30)}
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinejoin="round"
        vectorEffect="non-scaling-stroke"
      />
    </svg>
  );
}
